import assert from 'node:assert';
import { balanceDue, recordPayment } from '../src/payments.js';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';

const testInvoice = {
  customerId: 'C001',
  issueDate: '2024-01-15',
  lines: [
    { sku: 'WIDGET-A', qty: 2 },
    { sku: 'WIDGET-B', qty: 1 },
  ],
};

function createIssuedInvoice() {
  const created = createInvoice(testInvoice);
  if (!created.ok) throw new Error('Failed to create invoice');
  const issued = issueInvoice(created.value, []);
  if (!issued.ok) throw new Error('Failed to issue invoice');
  return issued.value;
}

describe('balanceDue', () => {
  it('returns total for issued invoice with no payments', () => {
    const invoice = createIssuedInvoice();
    const total = invoiceTotals(invoice).total;
    assert.strictEqual(balanceDue(invoice), total);
  });

  it('returns remaining balance after one payment', () => {
    const invoice = createIssuedInvoice();
    const total = invoiceTotals(invoice).total;
    const partialPayment = 5000;
    const paid = recordPayment(invoice, { amount: partialPayment, date: '2024-01-20' });
    assert(paid.ok);
    assert.strictEqual(balanceDue(paid.value), total - partialPayment);
  });

  it('returns zero after payment equals total', () => {
    const invoice = createIssuedInvoice();
    const total = invoiceTotals(invoice).total;
    const paid = recordPayment(invoice, { amount: total, date: '2024-01-20' });
    assert(paid.ok);
    assert.strictEqual(balanceDue(paid.value), 0);
  });

  it('returns remaining balance after multiple payments', () => {
    const invoice = createIssuedInvoice();
    const total = invoiceTotals(invoice).total;
    let result = recordPayment(invoice, { amount: 3000, date: '2024-01-20' });
    assert(result.ok);
    result = recordPayment(result.value, { amount: 2000, date: '2024-01-25' });
    assert(result.ok);
    assert.strictEqual(balanceDue(result.value), total - 5000);
  });
});

describe('recordPayment', () => {
  it('records payment on issued invoice', () => {
    const invoice = createIssuedInvoice();
    const result = recordPayment(invoice, { amount: 5000, date: '2024-01-20' });
    assert(result.ok);
    assert.strictEqual(result.value.payments.length, 1);
    assert.deepStrictEqual(result.value.payments[0], { amount: 5000, date: '2024-01-20' });
  });

  it('changes status to partially_paid after partial payment', () => {
    const invoice = createIssuedInvoice();
    const result = recordPayment(invoice, { amount: 5000, date: '2024-01-20' });
    assert(result.ok);
    assert.strictEqual(result.value.status, 'partially_paid');
  });

  it('changes status to paid when balance reaches zero', () => {
    const invoice = createIssuedInvoice();
    const total = invoiceTotals(invoice).total;
    const result = recordPayment(invoice, { amount: total, date: '2024-01-20' });
    assert(result.ok);
    assert.strictEqual(result.value.status, 'paid');
  });

  it('accepts payment on partially_paid invoice', () => {
    const invoice = createIssuedInvoice();
    let result = recordPayment(invoice, { amount: 5000, date: '2024-01-20' });
    assert(result.ok);
    assert.strictEqual(result.value.status, 'partially_paid');
    const total = invoiceTotals(invoice).total;
    result = recordPayment(result.value, { amount: total - 5000, date: '2024-01-25' });
    assert(result.ok);
    assert.strictEqual(result.value.status, 'paid');
  });

  it('fails with NOT_ISSUED for draft invoice', () => {
    const created = createInvoice(testInvoice);
    assert(created.ok);
    const result = recordPayment(created.value, { amount: 5000, date: '2024-01-20' });
    assert(!result.ok);
    assert.strictEqual(result.error, 'NOT_ISSUED');
  });

  it('fails with AMOUNT_INVALID for non-integer amount', () => {
    const invoice = createIssuedInvoice();
    const result = recordPayment(invoice, { amount: 50.5, date: '2024-01-20' });
    assert(!result.ok);
    assert.strictEqual(result.error, 'AMOUNT_INVALID');
  });

  it('fails with AMOUNT_INVALID for zero amount', () => {
    const invoice = createIssuedInvoice();
    const result = recordPayment(invoice, { amount: 0, date: '2024-01-20' });
    assert(!result.ok);
    assert.strictEqual(result.error, 'AMOUNT_INVALID');
  });

  it('fails with AMOUNT_INVALID for negative amount', () => {
    const invoice = createIssuedInvoice();
    const result = recordPayment(invoice, { amount: -1000, date: '2024-01-20' });
    assert(!result.ok);
    assert.strictEqual(result.error, 'AMOUNT_INVALID');
  });

  it('fails with OVERPAYMENT when payment exceeds balance', () => {
    const invoice = createIssuedInvoice();
    const total = invoiceTotals(invoice).total;
    const result = recordPayment(invoice, { amount: total + 1000, date: '2024-01-20' });
    assert(!result.ok);
    assert.strictEqual(result.error, 'OVERPAYMENT');
  });

  it('preserves invoice properties when recording payment', () => {
    const invoice = createIssuedInvoice();
    const result = recordPayment(invoice, { amount: 5000, date: '2024-01-20' });
    assert(result.ok);
    assert.strictEqual(result.value.customerId, invoice.customerId);
    assert.strictEqual(result.value.issueDate, invoice.issueDate);
    assert.strictEqual(result.value.number, invoice.number);
    assert.deepStrictEqual(result.value.lines, invoice.lines);
  });

  it('preserves existing payments when recording new payment', () => {
    const invoice = createIssuedInvoice();
    let result = recordPayment(invoice, { amount: 3000, date: '2024-01-20' });
    assert(result.ok);
    result = recordPayment(result.value, { amount: 2000, date: '2024-01-25' });
    assert(result.ok);
    assert.strictEqual(result.value.payments.length, 2);
    assert.deepStrictEqual(result.value.payments[0], { amount: 3000, date: '2024-01-20' });
    assert.deepStrictEqual(result.value.payments[1], { amount: 2000, date: '2024-01-25' });
  });
});

