    assert.strictEqual(result.value.payments.length, 2);
    assert.deepStrictEqual(result.value.payments[0], { amount: 3000, date: '2024-01-20' });
    assert.deepStrictEqual(result.value.payments[1], { amount: 2000, date: '2024-01-25' });
  });
});

